 public override void _UnhandledInput(InputEvent e){if(game==null)return;if(e is InputEventMouseMotion motion&&Input.MouseMode==Input.MouseModeEnum.Captured&&!paused){player.RotateY(-motion.Relative.X*.002f);pitch=Math.Clamp(pitch-motion.Relative.Y*.002f,-1.4f,1.4f);camera.Rotation=new Vector3(pitch,0,0);viewGunApplied=false;return;}
 if(FeverCinematic)return;if(e is InputEventMouseButton wheel&&wheel.Pressed&&!paused&&buildMode&&wheel.ButtonIndex is MouseButton.WheelUp or MouseButton.WheelDown){CycleBlueprint(wheel.ButtonIndex==MouseButton.WheelUp?1:-1);return;}if(e is InputEventMouseButton mouse&&mouse.Pressed&&!paused){if(Input.MouseMode!=Input.MouseModeEnum.Captured){Input.MouseMode=Input.MouseModeEnum.Captured;return;}if(mouse.ButtonIndex==MouseButton.Left){if(buildMode){if(demolitionMode)RemoveStructure();else PlaceStructure();}else if(axeEquipped)BeginAxeSwing();else Shoot();}if(mouse.ButtonIndex==MouseButton.Right){if(buildMode)RemoveStructure();else{aiming=!aiming;}}return;}
 if(e is not InputEventKey key||!key.Pressed||key.Echo)return;var k=key.PhysicalKeycode;if(k==Key.Escape){if(paused)CloseMenu();else ShowPause();return;}if(paused)return;if(k==Key.F&&mountedBlueprint!=null){Dismount();return;}
 if(k==Key.F2)ShowControls();else if(k==Key.F1)ShowFirstDay();else if(k==Key.F5)ShowJourneyPlanner();else if(k==Key.F4)ShowCampaignGuide();else if(k==Key.K)ShowCrafting();else if(k==Key.I)ShowEquipment();else if(k==Key.F7)ShowCommunity();else if(k==Key.J)ShowTalentTree();else if(k==Key.Y)ShowWounds();else if(k==Key.M&&dungeon==null)ShowMap();else if(k==Key.F6&&dungeon==null)ShowCamps();else if(k==Key.F8)ShowMultiplayer();else if(k==Key.N)ShowJournal();else if(k==Key.U){muted=!muted;if(ambience!=null)ambience.StreamPaused=muted;}else if(k==Key.L)lamp.Visible=!lamp.Visible;else if(k==Key.H){if(CoopRequest("bandage"))return;game.Change(()=>game.Notice=game.Life.Patch()?"Bandaged one wound / heals in 20 active minutes":"No open wound or no bandages");}else if(k==Key.V&&!CoopRequest("eat"))game.Change(()=>{if(game.Life.Food>0){game.Life.Food--;game.Life.Hunger=Math.Min(100,game.Life.Hunger+40);game.Notice="Ate provisions";}});else if(k==Key.C&&!CoopRequest("drink"))game.Change(()=>{if(game.Craft.Water>0){game.Drink();}else game.Notice="No clean water / Y to boil, filter, or risk untreated water";});else if(k==Key.B&&dungeon==null){buildMode=!buildMode;demolitionMode=false;if(!buildMode)ClearGhost();else ShowBuildCatalogue();}else if(buildMode){if(k==Key.Delete){demolitionMode=!demolitionMode;ClearGhost();}else if(k==Key.Tab)ShowBuildCatalogue();else if(k>=Key.Key1&&k<=Key.Key8)selectedBuild=(int)(k-Key.Key1);else if(k==Key.Q)yawBuild-=Input.IsPhysicalKeyPressed(Key.Ctrl)?1:15;else if(k==Key.E)yawBuild+=Input.IsPhysicalKeyPressed(Key.Ctrl)?1:15;else if(k==Key.G)snap=!snap;else if(k==Key.Pageup)heightBuild+=.1;else if(k==Key.Pagedown)heightBuild-=.1;else if(k==Key.Equal)reach=Math.Min(12,reach+.5);else if(k==Key.Minus)reach=Math.Max(2,reach-.5);else if(k==Key.R){heightBuild=0;yawBuild=0;}}
 else if(k==Key.F)Interact();else if(k==Key.G&&!buildMode){if(game.Craft.Throwable>=0)ThrowFieldItem();else ThrowDistraction();}else if(k==Key.F3)ShowFieldKit();else if(k==Key.Q&&!buildMode)StartChainFlame();else if(k==Key.R)StartReload();else if(!buildMode&&k>=Key.Key1&&k<=Key.Key3)SelectCombatClass((int)(k-Key.Key1));else if(k==Key.T){if(game.Craft.ToolLevels[game.Craft.HarvestTool]<1){game.Notice="Craft or select a harvesting tool / F3";return;}axePending=false;axeEquipped=!axeEquipped;BuildHeldTool();}else if(k==Key.P)PaintPath();else if(k==Key.O)DigWell();}
 public override void _PhysicsProcess(double dt){if(game==null||player==null)return;TickMusic(dt);shotClock=Math.Max(0,shotClock-dt);if((paused&&!CoopActive)||testing)return;if(CoopClient&&!coopReady){CoopTick(dt);return;}
 TickPrimitiveCombat(dt);UpdateCrouch(dt,!paused&&!buildMode&&!FeverCinematic&&Input.MouseMode==Input.MouseModeEnum.Captured&&Input.IsPhysicalKeyPressed(Key.Ctrl));if(TickMounted(dt)){aiming=false;game.Handling.Tick(game,dt,0,false,false);game.Sneaking=SetCrouch(player,false);TickStealth(dt,false);return;}bool moving=false,sprint=false;var v=player.Velocity;if(!paused&&!FeverCinematic&&Input.MouseMode==Input.MouseModeEnum.Captured){var dir=new Vector3((Input.IsPhysicalKeyPressed(Key.D)?1:0)-(Input.IsPhysicalKeyPressed(Key.A)?1:0),0,(Input.IsPhysicalKeyPressed(Key.S)?1:0)-(Input.IsPhysicalKeyPressed(Key.W)?1:0));dir=(player.Basis*dir).Normalized();moving=dir.LengthSquared()>.1f;if(game.Stamina>=25)exhausted=false;sprint=!aiming&&!game.Sneaking&&moving&&Input.IsPhysicalKeyPressed(Key.Shift)&&game.CanSprint&&!exhausted;float speed=(float)((game.Sneaking?2.2:sprint?9:4.8)*game.Speed*(aiming?.75:1));v.X=dir.X*speed;v.Z=dir.Z*speed;if(Input.IsPhysicalKeyPressed(Key.Space)&&!game.Sneaking&&player.IsOnFloor()){v.Y=6;Noise(14);}}else{v.X=0;v.Z=0;}
 v.Y-=18*(float)dt;player.Velocity=v;var old=player.Position;player.MoveAndSlide();if(dungeon==null&&!game.World.Playable(player.Position.X,player.Position.Z)){player.Position=old;game.Notice="River closed / future expansion boundary";}
 if(dungeon==null){game.Save.X=player.Position.X;game.Save.Z=player.Position.Z;StreamTerrain();SpawnObjects();}TickGunplay(dt,moving,sprint);TickChainCombat(dt);double worldTime=game.World.Changes.Time;if(game.Tick(dt,sprint)){if(!CoopClient){Die();return;}}if(CoopClient)game.World.Changes.Time=worldTime;AudioTick(moving,dt);if(game.Stamina<=6)exhausted=true;TickStealth(dt,sprint);
 if(CoopClient)reloadClock=Math.Max(0,reloadClock-dt);if(!CoopClient&&reloadClock>0){reloadClock-=dt;if(reloadClock<=0){game.Reload();game.Persist();}}if(buildMode&&!paused)UpdateGhost();TickMegaProjectiles(dt);TickFieldKit(dt);TickBaseSystems(dt);if(!CoopClient)TickEnemies(dt);spawnClock-=dt;if(!CoopClient&&spawnClock<=0){if(dungeon==null)SpawnInfected();spawnClock=2;}saveClock+=dt;if(saveClock>=10){game.Persist();saveClock=0;}
 CoopTick(dt);if(!paused&&Input.IsPhysicalKeyPressed(Key.P)&&game.Clock>nextPath)PaintPath();}
 public override void _Process(double dt){if(game==null||hud==null)return;UpdateHud();DrawFirstDay();TickImpactFeedback(dt);GunView(dt);TickBulletMarks();DrawChainEffects(dt);DrawMillEncounter();DrawScavengeTrap();DrawEnemyCues();DrawCommunity(dt);DrawCommunitySocial();DrawHuntingCarcasses();DrawRescueDog(dt);DrawLivingCommunities();DrawFamilyHouse(dt);DrawWoodlandCamp();DrawFeverStory(dt);DrawLastLetter(dt);DrawBirthday();DrawCheckpoint();DrawCrash();DrawDrone();DrawEncounters();DrawSpecialInfected();DrawCampaign();if(sun!=null){double light=.15+.85*Math.Clamp(Math.Sin((game.Hour-6)*Math.PI/12)*2,0,1);sun.LightEnergy=(float)(.04+light*.95);if(atmosphere.Environment.Sky?.SkyMaterial is ProceduralSkyMaterial sky){sky.SkyTopColor=new Color((float)(.055+.205*light),(float)(.075+.295*light),(float)(.12+.31*light));sky.SkyHorizonColor=new Color((float)(.10+.63*light),(float)(.13+.53*light),(float)(.18+.30*light));}sun.LightColor=new Color(1,.88f,.69f);sun.RotationDegrees=new Vector3((float)(-15-50*light),-30,0);atmosphere.Environment.AmbientLightEnergy=(float)(dungeon!=null?.23:.08+.45*light);atmosphere.Environment.BackgroundColor=new Color((float)(.10+.46*light),(float)(.13+.46*light),(float)(.16+.39*light));atmosphere.Environment.FogEnabled=true;atmosphere.Environment.FogSkyAffect=.1f;atmosphere.Environment.FogLightColor=new Color((float)(.12+.36*light),(float)(.16+.34*light),(float)(.22+.22*light));atmosphere.Environment.FogDensity=dungeon==null?.0016f:.008f;}DrawExpeditionWeather(dt);DrawCampLife(dt);if(relay!=null){RelayMessage msg;while(relay.Inbox.TryDequeue(out msg))game.Notice=msg.Op=="connected"?"Encrypted relay connected / session sync not ported":msg.Error??msg.Op;}}
